SELECT ro.recharge_id, ro.code, ro.create_time, ro.status, ro.type, ro.user_id, u.nickname, u.mobile, u.money, u.ext_money, ro.money AS order_money, ro.awards AS order_ext_money, ro.address_id, ba.short_name, ba.addr_name, ba.addr_person_name, ba.addr_person_mobile FROM recharge_order ro LEFT JOIN user u ON ro.user_id = u.id LEFT JOIN bluetooth_address ba ON ro.address_id = ba.id
AND ro.address_id = #{bean.addressId}
AND ro.user_id = #{bean.userId}
AND ro.status = #{bean.status}
AND ro.create_time >= #{bean.startDate}
AND ro.create_time <= #{bean.endDate}
AND u.mobile LIKE CONCAT('%', #{bean.mobile}, '%')
ORDER BY ro.create_time DESC
LIMIT #{page.pageSize} OFFSET #{page.offset}

