SELECT
    IFNULL(SUM(ro.money), 0) AS total_money,
    IFNULL(count(ro.money), 0) AS order_count,
    IFNULL(SUM(ro.awards), 0) AS total_awards
FROM recharge_order ro
WHERE 1 = 1

    AND ro.address_id = #{bean.addressId}


    AND ro.user_id = #{bean.userId}


    AND ro.status = #{bean.status}


    AND ro.create_time >= #{bean.startDate}


    AND ro.create_time <= #{bean.endDate}

SELECT id, code, user_id, recharge_id, address_id, status, create_time, money, awards, type
FROM recharge_order
WHERE code = #{code}
AND user_id = #{userId}
LIMIT 1

SELECT id, code, user_id, recharge_id, address_id, status, create_time, money, awards, type
FROM recharge_order
WHERE user_id = #{userId}
AND status = #{status}
ORDER BY create_time DESC
LIMIT 1

